	'ArrayExpression',
	'CallExpression',
	'Identifier',
	'Literal',
	'MemberExpression',
	'NewExpression',
	'ObjectExpression',
	'ParenthesizedExpression',
	'TemplateLiteral',
	'ThisExpression',
