	path: string,
	source: string,
	unhandled: readonly string[],
): CoreBindingMigration {
	return Object.freeze({
		path,
		source,
		changed: false,
		changes: Object.freeze([]),
		declaredDifferences: Object.freeze([]),
		unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
	});
}

