 * `require('util')` at all is a bundler that supplies those, because otherwise
 * the module it just resolved could not export anything.
 */
export const HOST_PROVIDED_GLOBAL_NAMES: readonly string[] = Object.freeze(
	[
		'AggregateError',
		'Array',
		'ArrayBuffer',
		'BigInt',
		'BigInt64Array',
		'BigUint64Array',
		'Boolean',
		'DataView',
		'Date',
		'Error',
		'EvalError',
		'FinalizationRegistry',
		'Float32Array',
		'Float64Array',
		'Function',
		'Infinity',
		'Int16Array',
		'Int32Array',
		'Int8Array',
		'Intl',
		'JSON',
		'Map',
		'Math',
		'NaN',
		'Number',
		'Object',
		'Promise',
		'Proxy',
		'RangeError',
		'ReferenceError',
		'Reflect',
		'RegExp',
		'Set',
		'SharedArrayBuffer',
		'String',
		'Symbol',
		'SyntaxError',
		'TypeError',
		'URIError',
		'Uint16Array',
		'Uint32Array',
		'Uint8Array',
		'Uint8ClampedArray',
		'WeakMap',
		'WeakRef',
		'WeakSet',
		'decodeURI',
		'decodeURIComponent',
		'encodeURI',
		'encodeURIComponent',
		'eval',
		'globalThis',
		'isFinite',
		'isNaN',
		'parseFloat',
		'parseInt',
		'undefined',
		// The CommonJS module wrapper's own parameters, plus `arguments`, which
		// every non-arrow function binds.
		'__dirname',
		'__filename',
