import path from 'pathe';
import type { WitnessFileSystem } from './filesystem.ts';

/**
 * Browser automation is a host capability, exactly like the filesystem:
 * library code never imports an automation driver itself. Hosts (the CLI bin,
 * test support) adapt a real driver — the owned CDP adapter at
 * `src/cli/browser-host.ts` in this repo — into this minimal surface and
 * inject it into `runBoxes()`.
 */
export type WitnessBrowser = {
	/** Driver/browser family name recorded in receipts, e.g. 'chromium'. */
	readonly name: string;
	launch(options: BrowserLaunchOptions): Promise<WitnessBrowserSession>;
};

export type BrowserLaunchOptions = {
	headless: boolean;
};

export type WitnessBrowserSession = {
	newPage(): Promise<WitnessBrowserPage>;
	close(): Promise<void>;
};

export type BrowserConsoleMessage = {
	/** Console method level: 'log', 'warning', 'error', ... */
	level: string;
	text: string;
};

export type BrowserPageError = {
	message: string;
};

export type BrowserRequestFailure = {
	url: string;
	method: string;
	reason: string | null;
};

export type BrowserNetworkConditions = {
	readonly offline?: boolean;
	/** CDP Network.emulateNetworkConditions latency, in milliseconds. */
	readonly latencyMs: number;
	/** CDP expects bytes per second, not bits per second. Use -1 to disable. */
	readonly downloadThroughputBytesPerSecond: number;
	/** CDP expects bytes per second, not bits per second. Use -1 to disable. */
	readonly uploadThroughputBytesPerSecond: number;
	readonly connectionType?:
		| 'none'
		| 'cellular2g'
		| 'cellular3g'
		| 'cellular4g'
		| 'bluetooth'
		| 'ethernet'
		| 'wifi'
		| 'wimax'
		| 'other';
};

export type BrowserNetworkRequest = {
	readonly url: string;
	readonly method: string;
	readonly resourceType: string | null;
	/** CDP monotonic timestamp in milliseconds. Relative ordering is stable. */
	readonly startTimeMs: number;
	readonly responseTimeMs: number | null;
	readonly endTimeMs: number | null;
	readonly durationMs: number | null;
	readonly status: number | null;
	readonly mimeType: string | null;
	readonly encodedDataLength: number | null;
	readonly failedReason: string | null;
	readonly initiatorType: string | null;
};

export type WitnessBrowserPage = {
	goto(url: string): Promise<void>;
	reload(): Promise<void>;
	/** Full serialized HTML of the current DOM. */
	content(): Promise<string>;
	/** Writes a PNG screenshot to the given absolute path. */
	screenshot(filePath: string): Promise<void>;
	/** Evaluates a JS expression in the page; the result must be JSON-serializable. */
	evaluate(expression: string): Promise<unknown>;
	/** Event-driven bounded wait until the expression evaluates truthy. */
	waitForExpression(expression: string, timeoutMs: number): Promise<void>;
	/** Clicks the first element matching the selector, waiting (bounded) for it to be actionable. */
	click(selector: string, timeoutMs: number): Promise<void>;
	/**
	 * Focuses the first writable element matching the selector and types text
	 * into it. Reports whether the target was a password field so evidence
	 * recording can force redaction.
	 */
	type(
		selector: string,
		text: string,
		options: { clear: boolean; keyEvents: boolean },
		timeoutMs: number,
	): Promise<{ passwordField: boolean }>;
	/** Moves the pointer over the first actionable element matching the selector. */
	hover(selector: string, modifiers: number, timeoutMs: number): Promise<void>;
	/** Focuses the element and dispatches one key (optionally chorded) to it. */
	press(selector: string, key: string, modifiers: number, timeoutMs: number): Promise<void>;
	/** Pointer drag from a source element to a target element or coordinates. */
	drag(
		from: string,
		to: string | { x: number; y: number },
		steps: number,
		timeoutMs: number,
	): Promise<void>;
	/** Wheel (or compositor-gesture) scroll at an element or the viewport. */
	scroll(
		target: string | null,
		deltaX: number,
		deltaY: number,
		gesture: boolean,
		timeoutMs: number,
	): Promise<void>;
	onConsoleMessage(listener: (message: BrowserConsoleMessage) => void): void;
	onPageError(listener: (error: BrowserPageError) => void): void;
	onRequestFailed(listener: (request: BrowserRequestFailure) => void): void;
	onNetworkRequest(listener: (request: BrowserNetworkRequest) => void): void;
	emulateNetwork(conditions: BrowserNetworkConditions): Promise<void>;
	clearNetworkEmulation(): Promise<void>;
	/** Fires on every main-frame navigation (reloads included). */
	onNavigated(listener: (url: string) => void): void;
	close(): Promise<void>;
};

